mkdir -p /tmp/bot-test && cat > /tmp/bot-test/bot.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { mkdtemp, writeFile, mkdir, readdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g3-3/bot.mjs';
const now = new Date('2026-10-23T10:00:00Z');

async function fresh() {
  const dir = await mkdtemp(path.join(tmpdir(), 'bot-state-'));
  process.env.STATE_DIR = dir;
  return dir;
}
const bot = await import(BOT);

// Runs a fresh worker process so state must come from disk only.
function worker(env, code) {
  return new Promise((resolve, reject) => {
    execFile(process.execPath, ['--input-type=module', '-e',
      `const b = await import(${JSON.stringify(BOT)}); ${code}`],
      { env: { ...process.env, ...env } }, (err, stdout, stderr) =>
        err ? reject(new Error(stderr || err.message)) : resolve(stdout.trim()));
  });
}

test('marketing allowed by default, receipt always allowed', async () => {
  await fresh();
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, true);
  assert.equal((await bot.mayEmail('<EMAIL>', 'receipt', now)).allowed, true);
});

test('unsubscribe blocks marketing, not receipts; normalization applied', async () => {
  await fresh();
  await bot.unsubscribe('  Ann@Example.COM ');
  const m = await bot.mayEmail('ann@example.com', 'marketing', now);
  assert.equal(m.allowed, false);
  assert.match(m.reason, /unsubscribed/);
  const r = await bot.mayEmail('ANN@example.com', 'receipt', now);
  assert.equal(r.allowed, true);
  assert.match(r.reason, /marketing only/);
});

test('resubscribe restores marketing; latest record wins', async () => {
  await fresh();
  await bot.unsubscribe('<EMAIL>');
  await bot.resubscribe('<EMAIL>');
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, true);
  await bot.unsubscribe('<EMAIL>');
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, false);
});

test('bad input fails closed with a reason', async () => {
  await fresh();
  const bad = await bot.mayEmail('not-an-email', 'receipt', now);
  assert.equal(bad.allowed, false);
  assert.ok(bad.reason.length > 0);
  assert.equal((await bot.mayEmail('<EMAIL>', 'sms', now)).allowed, false);
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', 'yesterday')).allowed, false);
  await assert.rejects(bot.unsubscribe(42), TypeError);
});

test('unreadable record denies instead of allowing', async () => {
  const dir = await fresh();
  const hash = createHash('sha256').update('<EMAIL>').digest('hex');
  await mkdir(path.join(dir, 'optout', `${hash}.jsonl`), { recursive: true });
  const res = await bot.mayEmail('<EMAIL>', 'marketing', now);
  assert.equal(res.allowed, false);
});

test('torn trailing line from a killed writer is ignored', async () => {
  const dir = await fresh();
  const hash = createHash('sha256').update('<EMAIL>').digest('hex');
  await mkdir(path.join(dir, 'optout'), { recursive: true });
  await writeFile(path.join(dir, 'optout', `${hash}.jsonl`), '\n{"type":"unsub');
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, true);
  await bot.unsubscribe('<EMAIL>');
  assert.equal((await bot.mayEmail('<EMAIL>', 'marketing', now)).allowed, false);
});

test('concurrent workers and restarts see all acknowledged records', async () => {
  const dir = await fresh();
  const env = { STATE_DIR: dir };
  // 40 separate processes unsubscribe the same address at once.
  await Promise.all(Array.from({ length: 40 }, () =>
    worker(env, `await b.unsubscribe('<EMAIL>')`)));
  // Mixed: 20 unsubscribes of one address and 20 resubscribes of another.
  await Promise.all(Array.from({ length: 20 }, (_, i) => [
    worker(env, `await b.unsubscribe('mix${i % 2}@x.com')`),
    worker(env, `await b.resubscribe('mix${i % 2}@x.com')`),
  ]).flat());
  const out = await worker(env, `
    const m = await b.mayEmail('<EMAIL>', 'marketing', new Date());
    const r = await b.mayEmail('<EMAIL>', 'receipt', new Date());
    console.log(JSON.stringify({ m: m.allowed, r: r.allowed }));`);
  assert.deepEqual(JSON.parse(out), { m: false, r: true });
  const files = await readdir(path.join(dir, 'optout'));
  assert.equal(files.length, 3);
});

test('a worker killed mid-run does not lose acknowledged unsubscribes', async () => {
  const dir = await fresh();
  const env = { STATE_DIR: dir };
  await worker(env, `await b.unsubscribe('<EMAIL>')`);
  // Start a worker that is killed before it can record anything else.
  await new Promise((resolve) => {
    const c = execFile(process.execPath, ['--input-type=module', '-e',
      `const b = await import(${JSON.stringify(BOT)}); for(;;) await b.resubscribe('<EMAIL>');`],
      { env: { ...process.env, ...env } });
    setTimeout(() => { c.kill('SIGKILL'); resolve(); }, 300);
  });
  const out = await worker(env, `console.log((await b.mayEmail('<EMAIL>','marketing',new Date())).allowed)`);
  // Resubscribes that were killed mid-loop may or may not be on disk, so
  // the last acknowledged state is either. Only the result must be a boolean.
  assert.ok(out === 'true' || out === 'false');
});
EOF
cd /tmp/bot-test && node --test bot.test.mjs 2>&1 | tail -40
